// src/chai/recordMervChaiAssertion.ts
function formatChaiValue(v) {
  if (v === void 0 || v === null) return null;
  if (typeof v === "string") return v;
  if (typeof v === "number" || typeof v === "boolean" || typeof v === "bigint") return String(v);
  try {
    return JSON.stringify(v);
  } catch {
    return String(v);
  }
}
function stepNameFromChai(message) {
  const m = String(message ?? "").trim();
  if (m) return m.length > 240 ? `${m.slice(0, 237)}\u2026` : m;
  return "Chai assertion";
}
function buildChaiPayload(input) {
  const stepName = stepNameFromChai(input.message);
  const expected = formatChaiValue(input.expected);
  const actual = formatChaiValue(input.actual);
  if (expected != null && actual != null) {
    return buildAssertionPayload(stepName, expected, actual);
  }
  if (input.passed) {
    return {
      stepType: "ASSERTION",
      teststepName: stepName,
      status: "PASSED",
      expected,
      actual,
      testdata: null,
      prereq: null,
      errorMessage: null
    };
  }
  return {
    stepType: "ASSERTION",
    teststepName: stepName,
    status: "FAILED",
    expected,
    actual,
    testdata: null,
    prereq: null,
    errorMessage: (input.errorMessage || stepName).trim() || "Chai assertion failed"
  };
}
function recordMervChaiAssertion(input) {
  const cfg = loadMervConfig();
  const payload = buildChaiPayload(input);
  if (!isStepCategoryAllowed(payload.stepType, cfg.allowedStepCategories)) {
    return;
  }
  const testInfo = getMervPlaywrightTestInfo();
  if (testInfo) {
    appendPendingPluginStep(testInfo, mervPluginPayloadToTestStep(payload));
    return;
  }
  const scenarioId = getActiveCucumberScenarioId();
  const session = getMervCucumberSessionInstance();
  if (scenarioId && session) {
    session.addPluginStepSync(scenarioId, payload);
  }
}

